    """

    if isinstance(batch, torch.Tensor):
        return batch.to(device, non_blocking=True)
    elif isinstance(batch, (tuple, list)):
        return type(batch)(to_cuda(elem, device, ignore_list) for elem in batch)
    elif isinstance(batch, dict):
        if "meta" in batch:
            batch_meta = batch.pop("meta")
        else:
            batch_meta = None
        new_batch = dotdict({k: to_cuda(v, device, ignore_list) for k, v in batch.items()})
        if batch_meta is not None:
            new_batch.meta = batch_meta
        return new_batch
    else:
        return batch
