class JPEGSerializer(Serializer):
    """The JPEGSerializer serialize and deserialize JPEG image to and from bytes."""

    def serialize(self, item: Image) -> Tuple[bytes, Optional[str]]:
        if isinstance(item, JpegImageFile):
            if hasattr(item, "filename") and os.path.exists(item.filename):
                with open(item.filename, "rb") as f:
                    return f.read(), None
            else:
                buffer = BytesIO()
                item.save(buffer, format="JPEG")
                return buffer.getvalue(), None
        elif isinstance(item, (PngImageFile, WebPImageFile, GifImageFile)):
            item = item.convert("RGB")
            buffer = BytesIO()
            item.save(buffer, format="JPEG")
            return buffer.getvalue(), None
        else:
            raise TypeError("Unsupported image type")
