def learning_rate_decay(
    step, lr_init, lr_final, max_steps, lr_delay_steps=0, lr_delay_mult=1
):

  # Calculate delay rate
  if lr_delay_steps > 0:
    delay_rate = 1 - 0.5 * (1 + jnp.cos(jnp.pi * (step / lr_delay_steps)))
  else:
    delay_rate = 1.0

  # Calculate learning rate
  if step < lr_delay_steps:
    learning_rate = lr_init * lr_delay_mult * delay_rate
  else:
    learning_rate = log_lerp(step / max_steps, lr_init, lr_final)

  return learning_rate
